// React hook shared by both apps: run `refresh` whenever the backend signals a
// change to any of `entities`. Debounced so a burst of writes (one load update
// touches loads + timeline) causes one refetch, not several.
import { useEffect, useRef } from 'react'
import type { ApiClient, ChangeEntity } from './api-client'

export function useLiveRefresh(
  client: ApiClient,
  entities: readonly ChangeEntity[],
  refresh: () => void,
  debounceMs = 300
): void {
  const refreshRef = useRef(refresh)
  useEffect(() => {
    refreshRef.current = refresh
  })

  const key = entities.join(',')
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined
    const unsubscribe = client.subscribe(key.split(',') as ChangeEntity[], () => {
      if (timer) clearTimeout(timer)
      timer = setTimeout(() => refreshRef.current(), debounceMs)
    })
    return () => {
      if (timer) clearTimeout(timer)
      unsubscribe()
    }
  }, [client, key, debounceMs])
}
